1	import { ClaimOfficeError, runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
6	
7	  return Buffer.concat(chunks).toString("utf8");
8	};
9	
10	const scenario = JSON.parse(await readStdin()) as Scenario;
11	
12	/**
13	 * The single stdout write sits inside the try deliberately: nothing is written
14	 * at all unless the whole scenario ran, so a rejected scenario cannot leave
15	 * partial results on stdout ahead of the message on stderr.
16	 */
17	try {
18	  process.stdout.write(`${JSON.stringify(runScenario(scenario))}\n`);
19	} catch (error) {
20	  /**
21	   * A scenario the office declines is reported plainly. Any other failure is a
22	   * defect rather than a verdict on the scenario, so it is left to surface with
23	   * its stack trace intact.
24	   */
25	  if (!(error instanceof ClaimOfficeError)) throw error;
26	
27	  process.stderr.write(`${error.message}\n`);
28	  process.exitCode = 1;
29	}
