1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  /** Zero-based index of the quote step that created the policy. */
30	  policy: number;
31	  incident: Incident;
32	}
33	
34	export type Step = QuoteStep | ClaimStep;
35	
36	export interface Scenario {
37	  customer: Customer;
38	  steps: Step[];
39	}
40	
41	export interface QuoteResult {
42	  premium: number;
43	}
44	
45	export interface ClaimResult {
46	  payout: number;
47	  remainingCap: number;
48	}
49	
50	export type StepResult = QuoteResult | ClaimResult;
51	
52	export interface ScenarioResults {
53	  results: StepResult[];
54	}
55	
56	/**
57	 * A customer as they stand at one point in a scenario: who they are, plus what
58	 * they have already been quoted. `quotesSoFar` counts *quotes priced*, not
59	 * steps taken — once claim steps exist the two will differ, and it is the quote
60	 * count that decides whether a policy is a follow-up contract.
61	 */
62	interface CustomerStanding {
63	  readonly customer: Customer;
64	  readonly quotesSoFar: number;
65	}
66	
67	const PROCESSING_FEE = 5;
68	
69	/**
70	 * The spec keeps intermediate amounts as exact fractions and rounds only the
71	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
72	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
73	 *
74	 * So percentages are applied as integer rationals — multiply by the numerator
75	 * first, divide by the denominator last — and money is carried in hundredths
76	 * of a G. Both operands of every product stay integral, so no drift accrues.
77	 */
78	const SUBUNITS_PER_G = 100;
79	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
80	
81	/**
82	 * A percentage held as an exact rational, so that it can be applied without
83	 * float drift: multiply by `num` first, divide by `den` last.
84	 *
85	 * Deliberately anonymous about *meaning*. Both sides of the business use
86	 * percentages, but they use them for opposite things — see `Rate` and `Share`,
87	 * which are the names the domain actually reads in.
88	 */
89	interface Fraction {
90	  num: number;
91	  den: number;
92	}
93	
94	/** The part of `subunits` that `fraction` denotes. */
95	const partOf = (subunits: number, fraction: Fraction): number =>
96	  (subunits * fraction.num) / fraction.den;
97	
98	/**
99	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
100	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
101	 * numerator. Modifiers are summed onto a base, never multiplied through it.
102	 */
103	type Rate = Fraction;
104	
105	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
106	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
107	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
108	
109	const LOYALTY_DISCOUNT: Rate = { num: -20, den: 100 };
110	const FOLLOW_UP_DISCOUNT: Rate = { num: -15, den: 100 };
111	
112	/** An item is highly enchanted from this level upwards. */
113	const HIGH_ENCHANTMENT_LEVEL = 5;
114	
115	/** A customer is long-standing from this many years of business upwards. */
116	const LOYALTY_YEARS = 2;
117	
118	/** The modifier amount `rate` contributes against `subunits` — not the total. */
119	const rateAmount = (subunits: number, rate: Rate): number => partOf(subunits, rate);
120	
121	/** Premiums round up — in the MHPCO's favour. */
122	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
123	
124	/**
125	 * What the MHPCO charges to insure an item type, and what it insures it for.
126	 * Two independent facts, held together because they are looked up together.
127	 *
128	 * Every insuranceValue here happens to be ten times its basePremium. That is a
129	 * coincidence of the current rate card, not a rule the spec states — the two
130	 * columns are given independently — so it is left unfactored. Deriving one from
131	 * the other would make a future type whose value is not 10x its premium
132	 * inexpressible.
133	 */
134	interface Rating {
135	  readonly basePremium: number;
136	  readonly insuranceValue: number;
137	  /** Components price in blocks; main items do not. */
138	  readonly isComponent: boolean;
139	}
140	
141	const RATE_CARD: Record<string, Rating> = {
142	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
143	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
144	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
145	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
146	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
147	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
148	};
149	
150	/**
151	 * A scenario the MHPCO declines to process — malformed input rather than a
152	 * business outcome. Thrown so that no partial results reach the caller; the CLI
153	 * catches it and reports the message, distinguishing it from an outright bug.
154	 */
155	export class ClaimOfficeError extends Error {}
156	
157	/** The MHPCO insures only what is on its price list. */
158	const ratingOf = (item: Item): Rating => {
159	  const rating = RATE_CARD[item.type];
160	  if (rating === undefined) throw new ClaimOfficeError(`Unknown item type: ${item.type}`);
161	
162	  return rating;
163	};
164	
165	const basePremiumOf = (item: Item): number => ratingOf(item).basePremium;
166	
167	/** What an item is insured for — distinct from what it costs to insure. */
168	const insuranceValueOf = (item: Item): number => ratingOf(item).insuranceValue;
169	
170	const isComponent = (item: Item): boolean => ratingOf(item).isComponent;
171	
172	/** Exactly this many alike components form a block, priced as one unit. */
173	const COMPONENT_BLOCK_SIZE = 3;
174	const COMPONENT_BLOCK_PREMIUM = 60;
175	
176	/** Splits items into those matching the predicate and those that do not. */
177	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
178	  items.filter(matches),
179	  items.filter((item) => !matches(item)),
180	];
181	
182	const groupByType = (items: Item[]): Map<string, Item[]> => {
183	  const groups = new Map<string, Item[]>();
184	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
185	
186	  return groups;
187	};
188	
189	const sumOfBasePremiums = (items: Item[]): number =>
190	  items.reduce((total, item) => total + basePremiumOf(item), 0);
191	
192	/**
193	 * Alike components — those of the very same type — form a block when there are
194	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
195	 * Any other count is priced per component.
196	 */
197	const componentGroupPremium = (group: Item[]): number =>
198	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
199	
200	/**
201	 * The policy base premium: every insured item's base premium, summed — except
202	 * that each group of alike components is priced as blocks where it can be.
203	 */
204	const policyBasePremiumOf = (items: Item[]): number => {
205	  const [components, mainItems] = partition(items, isComponent);
206	  const componentsTotal = [...groupByType(components).values()].reduce(
207	    (total, group) => total + componentGroupPremium(group),
208	    0,
209	  );
210	
211	  return sumOfBasePremiums(mainItems) + componentsTotal;
212	};
213	
214	/** The total the given rates contribute against a shared base. */
215	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
216	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
217	
218	const isHighlyEnchanted = (item: Item): boolean =>
219	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
220	
221	/** Which item-specific modifiers an item attracts, by its own attributes. */
222	const ratesForItem = (item: Item): Rate[] => [
223	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
224	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
225	];
226	
227	const isLongStanding = (standing: CustomerStanding): boolean =>
228	  standing.customer.yearsWithMHPCO >= LOYALTY_YEARS;
229	
230	const holdsAnEarlierQuote = (standing: CustomerStanding): boolean => standing.quotesSoFar > 0;
231	
232	/** Which policy-wide modifiers a policy attracts, by the customer's standing. */
233	const ratesForPolicy = (standing: CustomerStanding): Rate[] => [
234	  FIRST_INSURANCE_SURCHARGE,
235	  ...(isLongStanding(standing) ? [LOYALTY_DISCOUNT] : []),
236	  ...(holdsAnEarlierQuote(standing) ? [FOLLOW_UP_DISCOUNT] : []),
237	];
238	
239	/** Item-specific modifiers apply to the affected item's own base premium. */
240	const sumOfItemModifierAmounts = (items: Item[]): number =>
241	  items.reduce(
242	    (total, item) =>
243	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
244	    0,
245	  );
246	
247	/**
248	 * Modifiers are additive amounts, each computed against its own base: item
249	 * modifiers against the affected item, policy-wide modifiers against the
250	 * policy base premium. The processing fee is added at the very end.
251	 */
252	const quotePremium = (items: Item[], standing: CustomerStanding): number => {
253	  const policyBase = toSubunits(policyBasePremiumOf(items));
254	
255	  return toPremiumGold(
256	    policyBase +
257	      sumOfItemModifierAmounts(items) +
258	      sumOfRateAmounts(policyBase, ratesForPolicy(standing)) +
259	      toSubunits(PROCESSING_FEE),
260	  );
261	};
262	
263	/** A deductible is withheld from each damaged item's reimbursement. */
264	const DEDUCTIBLE = 100;
265	
266	/** The MHPCO pays at most this multiple of a policy's insurance sum. */
267	const CAP_MULTIPLE = 2;
268	
269	/** Payouts round down — in the MHPCO's favour. */
270	const toPayoutGold = (subunits: number): number => Math.floor(subunits / SUBUNITS_PER_G);
271	
272	/**
273	 * A policy created by a quote step: the items it covers, and how much of its
274	 * payout cap is still available.
275	 */
276	interface Policy {
277	  readonly items: Item[];
278	  readonly remainingCap: number;
279	}
280	
281	/**
282	 * What a policy insures for in total: every covered item's own insurance value,
283	 * summed. Unmodified — curses and enchantments move the premium, not this, and
284	 * a component block is a premium discount only.
285	 */
286	const insuranceSumOf = (items: Item[]): number =>
287	  items.reduce((total, item) => total + insuranceValueOf(item), 0);
288	
289	const policyFor = (items: Item[]): Policy => ({
290	  items,
291	  remainingCap: toSubunits(insuranceSumOf(items) * CAP_MULTIPLE),
292	});
293	
294	/**
295	 * How much of a damage the MHPCO reimburses, as an exact rational. Unlike a
296	 * `Rate`, a share is the *whole* of what is paid rather than an adjustment to
297	 * it: HALF_REIMBURSEMENT is what the claimant gets, not what they lose, and
298	 * FULL_REIMBURSEMENT is the identity. Shares are multiplied through the
299	 * damage; they are never summed with one another.
300	 */
301	type Share = Fraction;
302	
303	/** The part of `subunits` that `share` reimburses. */
304	const shareAmount = (subunits: number, share: Share): number => partOf(subunits, share);
305	
306	const FULL_REIMBURSEMENT: Share = { num: 100, den: 100 };
307	const HALF_REIMBURSEMENT: Share = { num: 50, den: 100 };
308	
309	/**
310	 * Damage to an item this heavily enchanted is reimbursed at half. Note this is
311	 * a different threshold from HIGH_ENCHANTMENT_LEVEL, which governs the premium.
312	 */
313	const HALF_REIMBURSEMENT_LEVEL = 8;
314	
315	const isHeavilyEnchanted = (item: Item): boolean =>
316	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL;
317	
318	/**
319	 * The share of a damage the MHPCO reimburses for an item.
320	 *
321	 * Reimbursement clauses do not stack the way premium modifiers do: exactly one
322	 * clause decides the share, and a share is multiplied through the damage rather
323	 * than summed. This is the opposite of `ratesForItem`, which collects every
324	 * modifier that applies — hence a single answer rather than a list.
325	 *
326	 * The spec also states a dragon-material clause granting *full* reimbursement,
327	 * and it is deliberately absent here. It is unobservable: full reimbursement is
328	 * already the default, and the only reducing clause (half, at enchantment >=
329	 * HALF_REIMBURSEMENT_LEVEL) is specified to win wherever both would apply. So
330	 * the dragon clause can only ever agree with this function, never override it —
331	 * no input exists for which reading `item.material` changes the answer. All
332	 * three worked dragon examples in the spec (enchantment 8 and 9 → half; 5 →
333	 * full) come out right without it.
334	 *
335	 * That makes a dragon branch unfalsifiable code: the suite stays green with it
336	 * above the enchantment check, below it, or gone. It is left out rather than
337	 * written untestable. Should a later clause make material observable — a
338	 * *reducing* dragon rule, or a full-reimbursement clause that outranks the
339	 * half — a failing test will demand it, and this note should go with it.
340	 */
341	const reimbursedShareOf = (item: Item): Share =>
342	  isHeavilyEnchanted(item) ? HALF_REIMBURSEMENT : FULL_REIMBURSEMENT;
343	
344	/**
345	 * What a damage is worth, in subunits.
346	 *
347	 * A damage cannot be worth less than nothing, so a negative amount is rejected
348	 * here rather than carried into the arithmetic. Were one allowed through, it
349	 * would not merely pay out negatively — it would *return* cap to the policy,
350	 * letting a later claim draw more than twice the insurance sum.
351	 *
352	 * Zero is left valid: a damage of exactly the deductible nets no payout and is
353	 * an ordinary, reportable outcome, not malformed input.
354	 */
355	const damageAmountOf = (damage: Damage): number => {
356	  if (damage.amount < 0) {
357	    throw new ClaimOfficeError(`Damage amount cannot be negative: ${damage.amount}`);
358	  }
359	
360	  return toSubunits(damage.amount);
361	};
362	
363	/**
364	 * What the MHPCO reimburses for one damaged item, before the cap is applied:
365	 * the reimbursed share of the damage, less the deductible.
366	 */
367	const reimbursementFor = (damage: Damage, item: Item): number =>
368	  shareAmount(damageAmountOf(damage), reimbursedShareOf(item)) - toSubunits(DEDUCTIBLE);
369	
370	/** Everything a step may read and advance as the scenario runs. */
371	interface Ledger {
372	  readonly standing: CustomerStanding;
373	  /** Policies by the index of the quote step that created them. */
374	  readonly policies: ReadonlyMap<number, Policy>;
375	}
376	
377	/** The ledger as it stands once `policy` is on record at `stepIndex`. */
378	const withPolicy = (ledger: Ledger, stepIndex: number, policy: Policy): Ledger => ({
379	  ...ledger,
380	  policies: new Map(ledger.policies).set(stepIndex, policy),
381	});
382	
383	/**
384	 * The policy created by the quote step at `stepIndex`.
385	 *
386	 * A claim names its policy by step index, and nothing constrains that index to
387	 * name a quote that happened — so the lookup rejects a dangling reference
388	 * rather than letting a claim proceed against no policy at all.
389	 */
390	const policyCreatedBy = (ledger: Ledger, stepIndex: number): Policy => {
391	  const policy = ledger.policies.get(stepIndex);
392	  if (policy === undefined) throw new ClaimOfficeError(`No policy created by step ${stepIndex}`);
393	
394	  return policy;
395	};
396	
397	/** A damage together with the insured item it befell. */
398	interface DamagedItem {
399	  readonly damage: Damage;
400	  readonly item: Item;
401	}
402	
403	/**
404	 * Each damage paired with the insured item it befell.
405	 *
406	 * A policy may cover several alike items — two swords, say — and each damage
407	 * entry is a separate item's misfortune. So a matched item is consumed: the
408	 * second sword damage pairs with the *other* sword, which may be enchanted
409	 * differently and so reimbursed differently.
410	 *
411	 * The pairing is returned joined rather than as an items list parallel to the
412	 * damages, so that a caller cannot read the two out of step.
413	 *
414	 * Finding no item to pair with is the *only* check on whether a policy covers
415	 * what was damaged. It is not merely an exhaustion guard: an item type can be
416	 * perfectly well known to the rate card — `ratingOf` would price an amulet
417	 * happily — and still be no part of *this* policy. Coverage is a fact about the
418	 * policy, not about the price list, so it can only be decided here.
419	 */
420	const pairDamagesWithItems = (policy: Policy, damages: Damage[]): DamagedItem[] => {
421	  const unharmed = [...policy.items];
422	
423	  return damages.map((damage) => {
424	    const found = unharmed.findIndex((covered) => covered.type === damage.itemType);
425	    if (found === -1) throw new ClaimOfficeError(`Policy does not cover a ${damage.itemType}`);
426	
427	    return { damage, item: unharmed.splice(found, 1)[0] };
428	  });
429	};
430	
431	/** The result of a step, and the ledger as the *next* step will find it. */
432	interface StepOutcome {
433	  readonly result: StepResult;
434	  readonly ledger: Ledger;
435	}
436	
437	/**
438	 * A quote prices the items against the customer's standing, and leaves the
439	 * customer holding one more quote than before — which is what makes the *next*
440	 * quote a follow-up. It also creates the policy that later claims draw on.
441	 */
442	const applyQuote = (step: QuoteStep, ledger: Ledger, stepIndex: number): StepOutcome => ({
443	  result: { premium: quotePremium(step.items, ledger.standing) },
444	  ledger: withPolicy(
445	    { ...ledger, standing: { ...ledger.standing, quotesSoFar: ledger.standing.quotesSoFar + 1 } },
446	    stepIndex,
447	    policyFor(step.items),
448	  ),
449	});
450	
451	/**
452	 * What an incident's damages come to against a policy, before the cap: every
453	 * damaged item reimbursed on its own terms, each less its own deductible.
454	 */
455	const reimbursementForIncident = (incident: Incident, policy: Policy): number =>
456	  pairDamagesWithItems(policy, incident.damages).reduce(
457	    (total, { damage, item }) => total + reimbursementFor(damage, item),
458	    0,
459	  );
460	
461	/**
462	 * What an incident actually pays out: what it is worth, or what the policy has
463	 * left, whichever is less.
464	 *
465	 * The cap binds the payout, not merely the report — a claim worth more than the
466	 * policy has left pays out only what remains. Clamping in subunits, before
467	 * `toPayoutGold` rounds, is what keeps the cap from running negative and lets it
468	 * reach exactly 0 rather than a rounded near-zero.
469	 */
470	const cappedPayout = (incident: Incident, policy: Policy): number =>
471	  Math.min(reimbursementForIncident(incident, policy), policy.remainingCap);
472	
473	/**
474	 * A claim reimburses each damaged item, less the deductible, and draws the
475	 * total down from the policy's remaining cap.
476	 */
477	const applyClaim = (step: ClaimStep, ledger: Ledger): StepOutcome => {
478	  const policy = policyCreatedBy(ledger, step.policy);
479	  const payout = cappedPayout(step.incident, policy);
480	  const remainingCap = policy.remainingCap - payout;
481	
482	  return {
483	    result: { payout: toPayoutGold(payout), remainingCap: toPayoutGold(remainingCap) },
484	    ledger: withPolicy(ledger, step.policy, { ...policy, remainingCap }),
485	  };
486	};
487	
488	/**
489	 * Steps are processed in order, since a step's result can depend on those
490	 * before it — a quote is discounted once the customer holds an earlier one, and
491	 * a claim draws on a policy an earlier quote created.
492	 *
493	 * Each step both produces a result and hands on the ledger the next step will
494	 * see, so that a step's effect on later steps lives with the step's own logic
495	 * rather than in loose accumulators advanced by hand here.
496	 */
497	export const runScenario = (scenario: Scenario): ScenarioResults => {
498	  const results: StepResult[] = [];
499	  let ledger: Ledger = {
500	    standing: { customer: scenario.customer, quotesSoFar: 0 },
501	    policies: new Map(),
502	  };
503	
504	  scenario.steps.forEach((step, stepIndex) => {
505	    const outcome =
506	      step.op === "quote" ? applyQuote(step, ledger, stepIndex) : applyClaim(step, ledger);
507	    results.push(outcome.result);
508	    ledger = outcome.ledger;
509	  });
510	
511	  return { results };
512	};
513
